 static xmlChar * htmlParseHTMLAttribute(htmlParserCtxtPtr ctxt, int stop);

+/**
+ * htmlStrndupInput:
+ * @ctxt: an HTML parser context
+ * @startPosition: offset from the current input base
+ * @len: number of bytes to duplicate
+ *
+ * Helper to safely duplicate a substring from the current parser input.
+ * The HTML parser sometimes stores offsets relative to BASE_PTR.
+ * If the input buffer is shrunk or replaced while scanning, BASE_PTR can
+ * change and a previously computed (BASE_PTR + startPosition) might no longer
+ * point into the current input buffer. In that case, blindly calling
+ * xmlStrndup can lead to out-of-bounds reads.
+ */
+static xmlChar *
+htmlStrndupInput(htmlParserCtxtPtr ctxt, size_t startPosition, size_t len) {
+    const xmlChar *base, *end, *start;
+
+    if ((ctxt == NULL) || (ctxt->input == NULL))
+        return(NULL);
+    base = ctxt->input->base;
+    end = ctxt->input->end;
+    if ((base == NULL) || (end == NULL) || (end < base))
+        return(NULL);
+
+    /* Validate that startPosition refers to the current input buffer. */
+    if (startPosition > (size_t)(end - base))
+        return(NULL);
+    start = base + startPosition;
+
+    /* Validate that len is within the available bytes and fits xmlStrndup(). */
+    if ((len > (size_t)(end - start)) || (len > INT_MAX))
+        return(NULL);
+
+    return(xmlStrndup(start, (int) len));
+}
+
